import java.util.Map;

/** The sheet's figures at one moment: each person's (by id, in the order they were added) and the
 *  sheet's totals, all as shown ("n/a" for a due-total with no figure). */
public record RollupFigures(Map<Long, PersonFigures> people, String claimedTotal, String dueTotal, String overdueTotal) {

    public record PersonFigures(String name, String claimed, String dueTotal, String overdueTotal, String score) {
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Takes the sheet's figures before a change, so the change can audit what it moved. */
public class SnapshotRollup {
    public void snapshot(@PathVariable("sheetId") String sheetId, Rollup rollup, Out<RollupFigures> before) {
        before.set(rollup.figures(sheetId));
    }
}
