                </td>
                <td data-testid="person-name">{shownName(p, today)}</td>
                {shown('aliases') && <td data-testid="person-aliases">{p.aliases.join(', ')}</td>}
                <td data-testid="person-clashing">{p.clashing ? 'yes' : 'no'}</td>
